import type { SupabaseClient } from "@supabase/supabase-js";
import { buildKitchenTicket, type KitchenTicketItem } from "./escpos";

export type KitchenPrintJob = {
  source: string;
  label: string;
  items: (KitchenTicketItem & { category: string | null })[];
};

// Ticket-building stays server-side (uses Buffer, reads kitchen_printers via
// the caller's Supabase client) — only the actual byte-sending moves to the
// client, since Vercel can never reach a printer's private LAN IP or a
// Bluetooth device, but the cashier's browser/app (physically on the shop's
// network, or physically holding the tablet) can. connectionType tells the
// client which transport to use: print-agent/native-LAN for "lan", the
// native Bluetooth plugin for "bluetooth" (browsers without the plugin can't
// do anything with a bluetooth job — see dispatch-print-jobs.ts).
export type KitchenPrintJobPayload = {
  printerName: string;
  address: string;
  connectionType: "lan" | "bluetooth";
  bytesBase64: string;
};

export async function buildKitchenPrintJobs(
  supabase: SupabaseClient,
  businessId: string,
  job: KitchenPrintJob,
): Promise<KitchenPrintJobPayload[]> {
  if (job.items.length === 0) return [];

  const { data: printers } = await supabase
    .from("kitchen_printers")
    .select("id, name, categories, connection_type, address, prints_receipt")
    .eq("business_id", businessId);

  // A printer marked prints_receipt is the cashier's receipt printer, not a
  // kitchen/bar station — it gets the priced customer receipt automatically
  // instead (see checkout()), so it's excluded here even if its categories
  // would otherwise match every item.
  const addressedPrinters = (printers ?? []).filter(
    (p) => !!p.address && !p.prints_receipt,
  ) as {
    id: string;
    name: string;
    categories: string[];
    connection_type: "lan" | "bluetooth";
    address: string;
  }[];

  const attempts = addressedPrinters
    .map((printer) => {
      const items =
        printer.categories.length > 0
          ? job.items.filter((i) => i.category && printer.categories.includes(i.category))
          : job.items;
      return { printer, items };
    })
    .filter((a) => a.items.length > 0);

  return attempts.map(({ printer, items }) => {
    const buffer = buildKitchenTicket({
      station: printer.name,
      source: job.source,
      label: job.label,
      items,
    });
    return {
      printerName: printer.name,
      address: printer.address,
      connectionType: printer.connection_type,
      bytesBase64: buffer.toString("base64"),
    };
  });
}

"use client";

import { Capacitor } from "@capacitor/core";
import { printViaAgent, type PrintAgentResult } from "./print-agent-client";
import KitchenPrinter from "./kitchen-printer-plugin";
import type { KitchenPrintJobPayload } from "./kitchen-print";
import { logKitchenPrintFailures } from "@/app/business/[businessId]/pos/actions";

// Android app (android-app/) supplies KitchenPrinter natively — the browser
// on the cashier's own tablet is on the shop's LAN (or physically holding
// it, for Bluetooth), so it can dial the printer directly, no print-agent PC
// needed. Plain browsers keep using the print-agent HTTP relay for LAN jobs
// (untouched); they have no way to reach a bluetooth job at all.
async function dispatchOne(job: KitchenPrintJobPayload): Promise<PrintAgentResult> {
  if (Capacitor.isNativePlatform()) {
    const result =
      job.connectionType === "lan"
        ? await (() => {
            const [ip, portStr] = job.address.split(":");
            const port = portStr ? Number(portStr) : 9100;
            return KitchenPrinter.printLan({ ip, port, bytesBase64: job.bytesBase64 });
          })()
        : await KitchenPrinter.printBluetooth({ address: job.address, bytesBase64: job.bytesBase64 });
    return result.ok
      ? { ok: true }
      : { ok: false, reason: "printer_unreachable", error: result.error ?? "unknown_error" };
  }
  if (job.connectionType === "bluetooth") {
    return { ok: false, reason: "printer_unreachable", error: "unsupported_on_web" };
  }
  return printViaAgent(job.address, job.bytesBase64);
}

export type DispatchedPrintResult = { job: KitchenPrintJobPayload; result: PrintAgentResult };

// Fire-and-forget from the checkout/order-status callers' point of view — a
// failed kitchen print must never block or fail the sale/order that
// triggered it (same principle the old server-side dispatchKitchenPrint
// followed), so they just `void` this call. The return value exists for
// callers that DO want to know per-job success/failure inline (e.g. a
// "Tes Cetak" button) — existing fire-and-forget callers are unaffected.
export async function dispatchPrintJobs(
  businessId: string,
  jobs: KitchenPrintJobPayload[],
): Promise<DispatchedPrintResult[]> {
  if (jobs.length === 0) return [];

  const results = await Promise.all(
    jobs.map(async (job) => ({ job, result: await dispatchOne(job) })),
  );

  const failed = results.filter((r) => !r.result.ok);
  if (failed.length > 0) {
    await logKitchenPrintFailures(
      businessId,
      failed.map(({ job, result }) => ({
        printer: job.printerName,
        error: result.ok ? "" : result.error,
      })),
    ).catch(() => {});
  }

  return results;
}

// Receipt jobs go out first and are awaited before the kitchen jobs start —
// two reasons: the cashier's receipt printer is often the same physical
// device as a kitchen station (Bluetooth sockets don't handle concurrent
// jobs well), and the customer copy is the priority print, not the kitchen
// ticket.
export async function dispatchReceiptThenKitchenJobs(
  businessId: string,
  receiptJobs: KitchenPrintJobPayload[],
  kitchenJobs: KitchenPrintJobPayload[],
) {
  await dispatchPrintJobs(businessId, receiptJobs);
  await dispatchPrintJobs(businessId, kitchenJobs);
}

import { idbDelete, idbGetAllByBusiness, idbPut } from "@/lib/offline-db";
import type { DiscountType } from "@/app/business/[businessId]/pos/actions";
import type { TicketCartItemInput } from "@/app/business/[businessId]/pos/ticket-actions";

export type PendingSaleStatus = "pending" | "syncing" | "error";

export type PendingRetailSale = {
  clientRef: string;
  businessId: string;
  kind: "retail";
  createdAt: string;
  status: PendingSaleStatus;
  errorMessage?: string;
  payload: {
    cashierId: string;
    items: { productId: string; qty: number; disc: number; discType: DiscountType }[];
    paymentMethod: string;
    received: number | null;
    orderDisc: number;
    orderDiscType: DiscountType;
    customerId: string | null;
    selfOrderIds: string[];
  };
};

export type PendingTicketSale = {
  clientRef: string;
  businessId: string;
  kind: "ticket";
  createdAt: string;
  status: PendingSaleStatus;
  errorMessage?: string;
  payload: {
    cashierId: string;
    items: TicketCartItemInput[];
    paymentMethod: string;
    received: number | null;
    memberId: string | null;
  };
};

export type PendingSale = PendingRetailSale | PendingTicketSale;

export async function enqueueSale(sale: PendingSale): Promise<void> {
  await idbPut(sale);
}

export async function listPending(businessId: string): Promise<PendingSale[]> {
  const rows = await idbGetAllByBusiness<PendingSale>(businessId);
  return rows.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
}

export async function markSyncing(sale: PendingSale): Promise<void> {
  await idbPut({ ...sale, status: "syncing", errorMessage: undefined });
}

export async function markSynced(clientRef: string): Promise<void> {
  await idbDelete(clientRef);
}

export async function markError(sale: PendingSale, message: string): Promise<void> {
  await idbPut({ ...sale, status: "error", errorMessage: message });
}

export async function discardPending(clientRef: string): Promise<void> {
  await idbDelete(clientRef);
}

// Stok server-side belum tahu apa-apa soal penjualan yang masih di antrian
// offline — kurangi tampilan stok kasir secara lokal supaya tidak menjual
// melebihi yang sebenarnya tersisa, sampai antrian ini tersinkron.
export function pendingStockDeltas(pending: PendingSale[]): Record<string, number> {
  const deltas: Record<string, number> = {};
  for (const sale of pending) {
    if (sale.kind !== "retail") continue;
    for (const item of sale.payload.items) {
      deltas[item.productId] = (deltas[item.productId] ?? 0) + item.qty;
    }
  }
  return deltas;
}
