// Wrapper tipis di atas IndexedDB bawaan browser — dipakai untuk menyimpan
// antrian penjualan yang gagal disinkronkan karena jaringan putus di
// pos-screen.tsx / ticket-pos-screen.tsx, dan (sejak v2) cache katalog POS
// (produk/open bill/customer) di pos-cache.ts untuk render instan di
// pembukaan berikutnya. Tidak ada dependency baru; hanya jalan di client
// (semua pemanggil harus mengecek `typeof window !== "undefined"` /
// dipanggil dari komponen "use client").

const DB_NAME = "kasirku-offline";
const DB_VERSION = 2;
const STORE_NAME = "pending_sales";
const POS_CACHE_STORE = "pos_cache";

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: "clientRef" });
        store.createIndex("by-business", "businessId", { unique: false });
      }
      if (!db.objectStoreNames.contains(POS_CACHE_STORE)) {
        db.createObjectStore(POS_CACHE_STORE, { keyPath: "businessId" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function idbPut<T>(record: T): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function idbGetAllByBusiness<T>(businessId: string): Promise<T[]> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const index = tx.objectStore(STORE_NAME).index("by-business");
    const request = index.getAll(IDBKeyRange.only(businessId));
    request.onsuccess = () => resolve(request.result as T[]);
    request.onerror = () => reject(request.error);
  });
}

export async function idbDelete(clientRef: string): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).delete(clientRef);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function idbPutPosCache<T>(record: T): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(POS_CACHE_STORE, "readwrite");
    tx.objectStore(POS_CACHE_STORE).put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function idbGetPosCache<T>(businessId: string): Promise<T | undefined> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(POS_CACHE_STORE, "readonly");
    const request = tx.objectStore(POS_CACHE_STORE).get(businessId);
    request.onsuccess = () => resolve(request.result as T | undefined);
    request.onerror = () => reject(request.error);
  });
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { checkout } from "@/app/business/[businessId]/pos/actions";
import { checkoutTicket } from "@/app/business/[businessId]/pos/ticket-actions";
import {
  discardPending,
  enqueueSale,
  listPending,
  markError,
  markSynced,
  markSyncing,
  type PendingSale,
} from "@/lib/offline-queue";
import { dispatchReceiptThenKitchenJobs } from "@/lib/dispatch-print-jobs";
import type { KitchenPrintJobPayload } from "@/lib/kitchen-print";

const SYNC_INTERVAL_MS = 20000;

// Dipakai di pos-screen.tsx & ticket-pos-screen.tsx. Melacak status
// online/offline browser, menyimpan/membaca antrian penjualan tertunda dari
// IndexedDB, dan mencoba sinkronkan ulang otomatis begitu koneksi kembali.
// Lihat rencana di plan file untuk kenapa desainnya begini — intinya: retry
// harus berurutan (bukan paralel) supaya konflik nomor tiket fisik
// terdeteksi satu-satu, dan idempotency (clientRef) di server yang menjamin
// retry yang mengulang penjualan yang sebenarnya sudah sukses tidak
// membuat transaksi duplikat.
export function useOfflineSync(businessId: string) {
  const [isOnline, setIsOnline] = useState(
    () => typeof navigator === "undefined" || navigator.onLine,
  );
  const [pending, setPending] = useState<PendingSale[]>([]);
  const syncingRef = useRef(false);

  const refresh = useCallback(async () => {
    const rows = await listPending(businessId);
    setPending(rows);
    return rows;
  }, [businessId]);

  const syncNow = useCallback(async () => {
    if (syncingRef.current) return;
    if (typeof navigator !== "undefined" && !navigator.onLine) return;
    syncingRef.current = true;
    try {
      const rows = await refresh();
      for (const sale of rows) {
        // Sudah gagal karena alasan bisnis (bukan jaringan) sebelumnya —
        // butuh tinjauan manual, jangan di-retry otomatis terus-menerus.
        if (sale.status === "error") continue;

        await markSyncing(sale);
        try {
          const result =
            sale.kind === "retail"
              ? await checkout(
                  sale.businessId,
                  sale.payload.cashierId,
                  sale.payload.items,
                  sale.payload.paymentMethod,
                  sale.payload.received,
                  sale.payload.orderDisc,
                  sale.payload.orderDiscType,
                  sale.payload.customerId,
                  sale.payload.selfOrderIds,
                  sale.clientRef,
                )
              : await checkoutTicket(
                  sale.businessId,
                  sale.payload.cashierId,
                  sale.payload.items,
                  sale.payload.paymentMethod,
                  sale.payload.received,
                  sale.payload.memberId,
                  sale.clientRef,
                );

          if (result.success) {
            await markSynced(sale.clientRef);
            // Only the "retail" checkout() path returns printJobs —
            // checkoutTicket() doesn't do kitchen printing at all.
            if (sale.kind === "retail") {
              const { printJobs, receiptPrintJobs } = result as unknown as {
                printJobs: KitchenPrintJobPayload[];
                receiptPrintJobs: KitchenPrintJobPayload[];
              };
              void dispatchReceiptThenKitchenJobs(sale.businessId, receiptPrintJobs, printJobs);
            }
          } else {
            await markError(sale, result.error);
          }
        } catch {
          // Masih gagal jaringan (timeout/koneksi putus lagi) — kembalikan
          // ke "pending", coba lagi di siklus sync berikutnya.
          await enqueueSale({ ...sale, status: "pending" });
        }
      }
    } finally {
      syncingRef.current = false;
      await refresh();
    }
  }, [refresh]);

  const discard = useCallback(
    async (clientRef: string) => {
      await discardPending(clientRef);
      await refresh();
    },
    [refresh],
  );

  useEffect(() => {
    // Fase 2 (cold-start offline): daftarkan service worker yang cache
    // halaman POS + aset statis, supaya reload/buka tab saat benar-benar
    // offline masih bisa menampilkan UI terakhir (lihat public/sw.js).
    // Idempotent — aman dipanggil di setiap mount/businessId berganti.
    if ("serviceWorker" in navigator) {
      navigator.serviceWorker
        .register("/sw.js", { scope: "/", updateViaCache: "none" })
        .catch(() => {});
    }
  }, []);

  useEffect(() => {
    listPending(businessId).then(setPending);

    function handleOnline() {
      setIsOnline(true);
      void syncNow();
    }
    function handleOffline() {
      setIsOnline(false);
    }

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, [businessId, syncNow]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (pending.length > 0) void syncNow();
    }, SYNC_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [pending.length, syncNow]);

  return { isOnline, pending, syncNow, discard };
}

